module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic bump_left,
    input  logic bump_right,
    input  logic ground,
    output logic walk_left,
    output logic walk_right,
    output logic aaah
);

    typedef enum logic [1:0] {
        S_LEFT       = 2'b00,
        S_RIGHT      = 2'b01,
        S_FALL_LEFT  = 2'b10,
        S_FALL_RIGHT = 2'b11
    } state_t;

    state_t state, next_state;

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= S_LEFT;
        end else begin
            state <= next_state;
        end
    end

    always_comb begin
        case (state)
            S_LEFT: begin
                if (!ground) 
                    next_state = S_FALL_LEFT;
                else if (bump_left && bump_right) 
                    next_state = S_RIGHT;
                else if (bump_left) 
                    next_state = S_RIGHT;
                else if (bump_right) 
                    next_state = S_LEFT;
                else 
                    next_state = S_LEFT;
            end
            S_RIGHT: begin
                if (!ground) 
                    next_state = S_FALL_RIGHT;
                else if (bump_left && bump_right) 
                    next_state = S_LEFT;
                else if (bump_left) 
                    next_state = S_RIGHT;
                else if (bump_right) 
                    next_state = S_LEFT;
                else 
                    next_state = S_RIGHT;
            end
            S_FALL_LEFT: begin
                if (ground) 
                    next_state = S_LEFT;
                else 
                    next_state = S_FALL_LEFT;
            end
            S_FALL_RIGHT: begin
                if (ground) 
                    next_state = S_RIGHT;
                else 
                    next_state = S_FALL_RIGHT;
            end
            default: next_state = S_LEFT;
        endcase
    end

    assign walk_left  = (state == S_LEFT);
    assign walk_right = (state == S_RIGHT);
    assign aaah       = (state == S_FALL_LEFT || state == S_FALL_RIGHT);

endmodule

